import React from "react";
import "./Header.css";

function Header() {
  return (
    <header className="header">
      <div className="header-content">
        <div className="text-section">
          <h1>Martin Donev</h1>
          <p>Computer Science Undergraduate @ Illinois State University</p>
        </div>
        <div className="image-section">
          <img src="/profile.jpg" alt="Martin Donev" className="profile-image" />
        </div>
      </div>
    </header>
  );
}

export default Header;
